import{z as l,x as o,o as B,c as d,q as s,j as A,D as e,d as t,s as n,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"TCB 最小化","description":"","frontmatter":{"title":"TCB 最小化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcb-minimization.md","filePath":"cs/tcb-minimization.md","lastUpdated":1791413859000}'),p={name:"cs/tcb-minimization.md"};function C(m,a,T,F,c,h){const i=o("Mermaid");return B(),d("div",null,[a[2]||(a[2]=s('<h1 id="tcb-最小化" tabindex="-1">TCB 最小化 <a class="header-anchor" href="#tcb-最小化" aria-label="Permalink to &quot;TCB 最小化&quot;">​</a></h1><div class="epigraph"><p>可信计算基是其正确性被依赖来强制策略的全体。体积越大越不能审。微内核、TEE、语言运行时都在削 TCB；seL4 把削完的核送进形式证明。</p><footer>—— 据 Lampson 对保护；Saltzer 经济机制；对照 Klein et al. seL4</footer></div><p>上一课<a href="/cs/defense-in-depth">纵深</a>给了多层防御；多层立刻引出新问题：<strong>每一层自己有多大，多少代码必须正确</strong>。本课 TCB 最小化回答的正是这件事——划清什么必须对、什么允许错。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单体内核加上全部驱动、解析器与文件系统都在 TCB 里：任何一行出错，安全策略即失守，而这套代码大到没有人能审完。缺口是两步操作：把尽量多的组件下推出信任基（用隔离和最小权限），再对剩下的核做验证或强审查。HSM 与 TEE 都是「削」的工程实例。</p><h3 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h3><p>编译器与硬件也在 TCB：源码正确不等于编译产物正确，Thompson 的 trusting trust 攻击表明被植入后门的编译器能在目标码里复制后门而不留源码痕迹；除非另行证明（可复现构建、形式验证），它们都得计入。</p><p><span class="marginnote">常见误区：初学者以为「代码开源=可信」。实际上编译产物可以和源码不一致——被做手脚的编译器会识别出「自己正在编译自己」，把后门写进新编译器且源码里无痕；打破这条链要靠可复现构建或对工具链本身做证明。</span></p><p><span class="marginnote">直觉类比：TCB 像登机安检链条——安检仪、安检员、登机口核对，任何一环被收买，整套安检即作废。链条上每多一环，需要保证可靠的东西就多一份，所以「少而精」的链条才审得动。</span></p><p><span class="marginnote">Lampson。SDL 下一课是过程；seL4 是形式化封口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先是盘点：对给定系统列出「错了即策略失守」的组件清单，这一步常让人第一次看清 TCB 的真实体积。再对照微内核路线：把驱动、文件系统、网络栈移出内核态，只留 IPC、调度与基本内存管理。清单缩短之后，审查与证明才有落点。下一课 SDL，再 seL4。</p>',13)),(B(),A(r,null,{default:e(()=>[n(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E5%AE%89%E5%85%A8%E7%AD%96%E7%95%A5%22%5D%20--%3E%20TCB%5B%22%E5%BF%85%E9%A1%BB%E6%AD%A3%E7%A1%AE%E7%9A%84%E5%9F%BA%22%5D%0A%20%20TCB%20--%3E%20SMALL%5B%22%E8%B6%8A%E5%B0%8F%E8%B6%8A%E5%8F%AF%E5%AE%A1%22%5D%0A%20%20REST%5B%22%E5%9F%BA%E5%A4%96%E7%BB%84%E4%BB%B6%22%5D%20--%3E%20UNTRUST%5B%22%E5%8F%AF%E9%94%99%E5%8F%AF%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"纵深的每一预防层都有自己的 TCB：WAF 的规则引擎、MFA 的令牌校验、内核的访问控制，谁错了谁的层即穿。因此体积决定可审性：几百行的引用监视器可以逐行读完并证明，千万行的巨内核只能抽样测试。seL4 是这条路线的终点示范——先把微内核削到约万行 C，再用机器检查的证明封住「实现符合规范」。SDL 管如何造（过程），seL4 管如何证（产物）。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：seL4 把内核削到约 1 万行 C，配上的机器检查证明约 20 万行；对照通用 Linux 内核超过 3000 万行——逐行审计 1 万行可行，3000 万行只能抽样测试，这就是「先削再证」的量化动机。")],-1)),(B(),A(r,null,{default:e(()=>[n(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%9B%AE%E6%A0%87%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20INV%5B%22%E7%9B%98%E7%82%B9%EF%BC%9A%E8%B0%81%E9%94%99%E4%BA%86%E7%AD%96%E7%95%A5%E5%B0%B1%E5%A4%B1%E5%AE%88%EF%BC%9F%22%5D%0A%20%20INV%20--%3E%20BIG%5B%22%E5%8D%95%E4%BD%93%EF%BC%9A%E9%A9%B1%E5%8A%A8%2F%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%2F%E7%BD%91%E7%BB%9C%E6%A0%88%E5%85%A8%E5%9C%A8%E5%9F%BA%E5%86%85%22%5D%0A%20%20INV%20--%3E%20Q%7B%22%E8%83%BD%E9%9A%94%E7%A6%BB%E4%B8%8B%E6%8E%A8%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20SMALL%5B%22%E7%A7%BB%E5%87%BA%E5%9F%BA%EF%BC%9A%E5%BE%AE%E5%86%85%E6%A0%B8%E5%8F%AA%E7%95%99%20IPC%2F%E8%B0%83%E5%BA%A6%2F%E5%86%85%E5%AD%98%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20KEEP%5B%22%E7%95%99%E5%9C%A8%E5%9F%BA%E5%86%85%EF%BC%9A%E9%80%90%E8%A1%8C%E5%AE%A1%E6%88%96%E8%AF%81%E6%98%8E%22%5D%0A%20%20SMALL%20--%3E%20PROVE%5B%22%E5%9F%BA%E5%B0%8F%E5%88%B0%E5%8F%AF%E6%9C%BA%E5%99%A8%E9%AA%8C%E8%AF%81%EF%BC%8C%E5%A6%82%20seL4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有系统都改写成微内核：削 TCB 有真实代价，单核的 IPC 开销与生态迁移成本摆在那里；对既有系统，先量出 TCB 再决定削哪里，比推倒重来常见得多。SDL 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纵深每层都有 TCB。</li><li>体积决定能否审与证。</li><li>隔离把组件移出基。</li><li>下一课 SDL。</li><li>出处：Lampson；Saltzer and Schroeder；Klein et al.（下下课）。</li></ul>',4))])}const L=l(p,[["render",C]]);export{u as __pageData,L as default};
